import { test, expect } from '@playwright/test';

test.describe('In-App Notifications Real-Time Update', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display new notifications in real-time without page refresh', async ({ page }) => {
    // Verify initial notification count
    const notificationBadge = page.getByRole('status', { name: /notifications/i });
    await expect(notificationBadge).toBeVisible();
    const initialCount = await notificationBadge.textContent();
    expect(initialCount).toContain('0');

    // Intercept the WebSocket connection
    await page.route('**/ws/notifications', (route) => {
      route.continue();
    });

    // Verify WebSocket connection is established
    const wsElement = page.locator('[data-testid="websocket-connection"]');
    await expect(wsElement).toBeVisible();

    // Simulate a new notification via WebSocket
    await page.route('**/ws/notifications', (route) => {
      route.abort();
    });
    await page.route('**/ws/notifications', (route) => {
      route.continue();
    });

    // Wait for the notification to appear
    await page.waitForTimeout(500);

    // Verify notification badge updates
    await expect(notificationBadge).toContainText('1');

    // Verify notification list item appears
    const notificationItem = page.getByRole('listitem', { name: /new notification/i });
    await expect(notificationItem).toBeVisible();

    // Verify notification content is displayed
    const notificationText = page.getByText('You have a new notification');
    await expect(notificationText).toBeVisible();

    // Verify notification has a timestamp
    const timestamp = page.getByText(/just now/i);
    await expect(timestamp).toBeVisible();
  });

  test('should handle multiple real-time notifications and clear badge on read', async ({ page }) => {
    // Verify initial notification count
    const notificationBadge = page.getByRole('status', { name: /notifications/i });
    await expect(notificationBadge).toBeVisible();
    const initialCount = await notificationBadge.textContent();
    expect(initialCount).toContain('0');

    // Intercept WebSocket and simulate multiple notifications
    await page.route('**/ws/notifications', (route) => {
      route.continue();
    });

    // Simulate first notification
    await page.route('**/ws/notifications', (route) => {
      route.abort();
    });
    await page.route('**/ws/notifications', (route) => {
      route.continue();
    });
    await page.waitForTimeout(500);
    await expect(notificationBadge).toContainText('1');

    // Simulate second notification
    await page.route('**/ws/notifications', (route) => {
      route.abort();
    });
    await page.route('**/ws/notifications', (route) => {
      route.continue();
    });
    await page.waitForTimeout(500);
    await expect(notificationBadge).toContainText('2');

    // Verify both notifications are visible
    const notificationItems = page.getByRole('listitem', { name: /new notification/i });
    await expect(notificationItems).toHaveCount(2);

    // Click on the first notification to mark as read
    const firstNotification = page.getByRole('listitem', { name: /new notification/i }).first();
    await firstNotification.click();

    // Verify notification badge count decreases
    await expect(notificationBadge).toContainText('1');

    // Verify notification is marked as read
    const readNotification = page.getByText(/read/i);
    await expect(readNotification).toBeVisible();

    // Verify unread notification still exists
    const unreadNotification = page.getByRole('listitem', { name: /new notification/i }).last();
    await expect(unreadNotification).toBeVisible();
    await expect(unreadNotification).not.toContainText('read');
  });
});
